import { recipe } from '../detail-helpers-v1.js';
import { motifs } from '../economy-traditions.js';
import { workTasks } from '../economy-workflows.js';
import { goodsTasks } from './workflows.js';
const practices={
  service:'Appointments are agreed directly with the customer.|The keeper confirms the requested time before booking.|Customers can ask about the scope of a visit.|Changes to appointments go through the keeper.|The customer receives a copy of the booking details.|Special arrangements are discussed before booking.|The keeper asks who should receive any messages.|The customer can choose from the available times.|The keeper confirms what the appointment covers.|Customers can ask for a follow-up visit.',
  provisions:'Containers are labeled before collection.|Customers can ask where supplies came from.|The keeper checks the quantity before packing.|Repeat customers can arrange a regular collection.|Small samples are available before a larger purchase.|Packing is chosen to suit the goods.|The keeper confirms the collection date.|Substitutions are discussed before packing.|The customer can bring a suitable container.|The keeper checks the stock before accepting a large order.',
  documents:'Names and spellings are checked with the customer.|A draft is shown before the final copy is prepared.|Customers can point out changes on a working copy.|The keeper confirms which version the customer needs.|Reference notes stay with the job until it is complete.|The customer can ask for an extra copy.|Corrections are discussed before the final version.|The keeper checks which names should appear.|The customer is asked how the finished copy will be used.|Special wording is agreed before the work begins.',
  goods:'The keeper checks the goods before handover.|Customers can inspect a sample before buying.|Collection times are agreed with the customer.|Goods are packed to suit the journey.|The keeper confirms the quantity before collection.|Customers can ask about the available sizes.|Special requests are discussed before ordering.|The customer can compare the available stock.|The keeper checks the requested item before packing.|Delivery arrangements are agreed before purchase.'
};
export const practicalTraditions=Object.fromEntries(Object.entries(practices).map(([flow,values])=>[flow,Object.fromEntries(Object.entries(motifs).map(([ancestry,marks])=>[ancestry,recipe(marks.split('|').map(m=>`${flow==='service'?'Notices':flow==='documents'?'Document covers':'Labels'} at {displayName} use ${m}.`),values)]))]));
const requests='{fullName} asks someone to|{fullName} needs help to|The keeper at {displayName} is looking for someone to|A caller at {displayName} asks for help to|{fullName} would like someone to|A notice at {displayName} asks someone to|The keeper at {displayName} needs someone to|{fullName} is seeking help to|A customer at {displayName} wants someone to|{fullName} has asked for someone to';
export const workLeads=Object.fromEntries([...Object.entries(workTasks).map(([key,values])=>[key,values.split('|')]),['goods',goodsTasks]].map(([key,values])=>[key,recipe(requests,values.map(v=>`${v}.`))]));
export const currentWork=Object.fromEntries([...Object.entries(workTasks).map(([key,values])=>[key,values.split('|')]),['goods',goodsTasks]].map(([key,values])=>[key,recipe('For {customer}, the next job is to|A request from {customer} calls for someone to|The work for {customer} needs someone to|For the work requested by {customer}, someone must|On the request from {customer}, the next step is to|The current job for {customer} requires someone to|The enquiry from {customer} asks someone to|For the enquiry from {customer}, someone needs to|The next task for {customer} is to|The request from {customer} requires someone to',values.map(v=>`${v}.`))]));
